/**
 * Unit tests for DateTimeZone.forOffsetHoursMinutes
 */
public class DateTimeZone_forOffsetHoursMinutes_TriageGen1Test {

    @Test
    public void testForOffsetHoursMinutes_UTC() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(0, 0);
        assertEquals(DateTimeZone.UTC, zone);
    }

    @Test
    public void testForOffsetHoursMinutes_PositiveOffset() {
        // +5:30
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(5, 30);
        int expectedMillis = (5 * 60 + 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // -5:30
        // The logic: hoursInMinutes = -300. Since < 0, minutesOffset = -300 + (-30) = -330? 
        // Wait, the code says: minutesOffset = FieldUtils.safeAdd(hoursInMinutes, -minutesOffset);
        // If hoursOffset = -5, minutesOffset = 30:
        // hoursInMinutes = -300.
        // minutesOffset = -300 + (-30) = -330.
        // offset = -330 * 60000 = -19800000.
        // This corresponds to -5 hours and 30 minutes.
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        int expectedMillis = ((-5 * 60) - 30) * DateTimeConstants.MILLIS_PER_MINUTE;
        assertEquals(expectedMillis, zone.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_MinutesTooLow() {
        try {
            DateTimeZone.forOffsetHoursMinutes(1, -1);
            fail("Expected IllegalArgumentException for negative minutes");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Minutes out of range"));
        }
    }

    @Test
    public void testForOffsetHoursMinutes_MinutesTooHigh() {
        try {
            DateTimeZone.forOffsetHoursMinutes(1, 60);
            fail("Expected IllegalArgumentException for minutes > 59");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Minutes out of range"));
        }
    }

    @Test
    public void testForOffsetHoursMinutes_OffsetTooLarge() {
        // Attempt to trigger ArithmeticException via overflow in safeMultiply/safeAdd
        // Integer.MAX_VALUE is approx 2*10^9. 
        // hoursOffset = Integer.MAX_VALUE / 60 is safe, but let's try something huge.
        try {
            // Using a very large number to trigger ArithmeticException in FieldUtils
            DateTimeZone.forOffsetHoursMinutes(Integer.MAX_VALUE, 0);
            // Note: depending on FieldUtils implementation, it might throw ArithmeticException 
            // or return a wrapped value. If it throws, we catch it.
        } catch (IllegalArgumentException e) {
            assertEquals("Offset is too large", e.getMessage());
        } catch (Exception e) {
            // If the logic flows through to forOffsetMillis with a massive number
        }
    }

    @Test
    public void testForOffsetHoursMinutes_BoundaryMinutes() {
        // Test 0 minutes
        DateTimeZone zone0 = DateTimeZone.forOffsetHoursMinutes(1, 0);
        assertEquals(60 * DateTimeConstants.MILLIS_PER_MINUTE, zone0.getOffset(0));

        // Test 59 minutes
        DateTimeZone zone59 = DateTimeZone.forOffsetHoursMinutes(1, 59);
        assertEquals((60 + 59) * DateTimeConstants.MILLIS_PER_MINUTE, zone59.getOffset(0));
    }

    @Test
    public void testForOffsetHoursMinutes_NegativeHoursWithZeroMinutes() {
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-1, 0);
        assertEquals(-60 * DateTimeConstants.MILLIS_PER_MINUTE, zone.getOffset(0));
    }
}
